    "_{servers} and %n other server_::_{servers} and %n other servers_" : ["{servers} a %n gweinydd arall", "{servers} a %n gweinyddion eraill", "{servers} a %n gweinyddion eraill", "{servers} a %n gweinyddion eraill"],
    "Busy on {servers}, and used here" : "Yn brysur ar {servers}, ac yn cael ei ddefnyddio yma",
